const requester = $input.first().json;
const body = $('Webhook - Save Automation').first().json.body || {};
if (!requester.id || !requester.active) throw new Error('Invalid session.');
if (requester.role !== 'admin') throw new Error('Only admins can create or edit automations.');

const OPERATORS = ['equals', 'not_equals', 'contains', 'greater_than', 'less_than', 'is_true', 'is_false'];
const WAIT_UNITS = ['minutes', 'hours', 'days', 'months'];
const EMAIL_RE = /^[^\s@<>"'`,;()\[\]\\]+@[^\s@<>"'`,;()\[\]\\]+\.[^\s@<>"'`,;()\[\]\\]{2,}$/;
const str = (v) => (typeof v === 'string' || typeof v === 'number' ? String(v).trim() : '');
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const MAX_STEPS = 50;
// What each action needs in its saved config — the same rules the builder form enforces, so a hand-built or
// scripted request can't save an automation that would silently do nothing (or fail every poll) when it runs.
function checkConfig(type, cfg, n) {
  const at = `Step ${n}`;
  if (!isObj(cfg)) throw new Error(`${at} needs a configuration object.`);
  switch (type) {
    case 'add_tag': case 'remove_tag':
      if (!str(cfg.tag_name)) throw new Error(`${at} needs a tag name.`); break;
    case 'send_email':
      if (!str(cfg.subject)) throw new Error(`${at} needs an email subject.`); break;
    case 'send_team_notification':
      if (!str(cfg.message)) throw new Error(`${at} needs a message.`);
      if (!cfg.channel_id) throw new Error(`${at} needs a Team Chat channel.`); break;
    case 'send_dm': case 'send_sms': case 'send_telegram':
      if (!str(cfg.message)) throw new Error(`${at} needs a message.`); break;
    case 'create_task':
      if (!str(cfg.subject)) throw new Error(`${at} needs a task subject.`); break;
    case 'wait':
      if (!(Number(cfg.amount) > 0) || !Number.isFinite(Number(cfg.amount))) throw new Error(`${at} needs a wait duration greater than 0.`);
      if (!WAIT_UNITS.includes(cfg.unit)) throw new Error(`${at} needs a wait unit of ${WAIT_UNITS.join(', ')}.`); break;
    case 'update_field':
      if (!str(cfg.field)) throw new Error(`${at} needs a field.`);
      if (cfg.value === undefined || cfg.value === null || cfg.value === '') throw new Error(`${at} needs a value.`); break;
    case 'condition':
      if (!str(cfg.field) || str(cfg.field).length > 100) throw new Error(`${at} needs a condition field.`);
      if (!OPERATORS.includes(cfg.operator)) throw new Error(`${at} has an invalid condition operator.`); break;
    default: break;
  }
}

const VALID_TRIGGER_TYPES = ['contact', 'company', 'task', 'calendar', 'pipeline'];
// 'condition' is structural (nests other steps under it via parent_step_key
// below), not something the Engine ever executes as a side-effecting
// action — see n8n-workflows/automation_actions_tree_add.sql.
const VALID_ACTION_TYPES = ['add_tag', 'remove_tag', 'send_email', 'send_team_notification', 'send_sms', 'send_telegram', 'wait', 'update_field', 'mark_closed_won', 'mark_closed_lost', 'create_task', 'send_dm', 'ai_triage', 'condition', 'branch_if', 'assign_owner_round_robin', 'enroll_nurture'];
// 'created' (webhook-triggered) and 'inactive' (schedule-triggered, polls
// on its own dedicated Schedule Trigger) are compiler-supported today.
const VALID_TRIGGER_EVENTS = ['created', 'inactive'];

let id = null;
if (body.id !== undefined && body.id !== null && body.id !== '') {
  id = Number(body.id);
  if (!Number.isInteger(id) || id <= 0) throw new Error('"id" must be a valid automation id.');
}
const name = str(body.name);
const triggerType = str(body.trigger_type);
if (!name) throw new Error('"name" is required.');
if (name.length > 200) throw new Error('"name" is too long (maximum 200 characters).');
if (!VALID_TRIGGER_TYPES.includes(triggerType)) throw new Error('"trigger_type" is invalid.');

const triggerEvent = body.trigger_event ? str(body.trigger_event) : null;
if (triggerEvent && !VALID_TRIGGER_EVENTS.includes(triggerEvent)) throw new Error('"trigger_event" is invalid.');

// 'created' doesn't use the old field/operator/value condition at all —
// the event itself is the trigger. Everything else (no event, or 'inactive',
// which uses trigger_config to express "N days since last activity") keeps
// requiring a fully configured condition, exactly as before.
const triggerConfig = isObj(body.trigger_config) ? body.trigger_config : {};
if (triggerEvent !== 'created') {
  if (!str(triggerConfig.field) || !triggerConfig.operator || triggerConfig.value === undefined || triggerConfig.value === '') {
    throw new Error('A fully configured trigger is required.');
  }
  if (str(triggerConfig.field).length > 100) throw new Error('The trigger field is too long.');
  if (!OPERATORS.includes(triggerConfig.operator)) throw new Error('The trigger has an invalid operator.');
  if (String(triggerConfig.value).length > 500) throw new Error('The trigger value is too long (maximum 500 characters).');
}

// condition_tree is kept only for whatever pre-existing rows still have it
// (read-only, never written by new saves) — a condition can now appear
// anywhere in the step tree below instead of being this one fixed,
// top-level slot. New saves always send null here.
const conditionTree = null;

const rawActions = Array.isArray(body.actions) ? body.actions : [];
if (rawActions.length === 0) throw new Error('At least one action is required.');
if (rawActions.length > MAX_STEPS) throw new Error(`An automation can have at most ${MAX_STEPS} steps.`);

// step_key/parent_step_key are plain client-assigned integers (not a DB
// foreign key) that let a step nest under a 'condition' step anywhere in
// the tree, at any depth — see automation_actions_tree_add.sql for why
// this shape sidesteps needing multi-pass inserts. Every step needs a
// unique step_key; a non-null parent_step_key must point at another step
// IN THIS SAME PAYLOAD whose action_type is 'condition'.
const stepKeys = new Set();
for (const a of rawActions) {
  if (!isObj(a)) throw new Error('Every step must be an object.');
  const k = Number(a.step_key);
  if (!Number.isInteger(k)) throw new Error('Every step needs a step_key.');
  if (stepKeys.has(k)) throw new Error(`Duplicate step_key ${k}.`);
  stepKeys.add(k);
}
const conditionStepKeys = new Set(rawActions.filter((a) => a.action_type === 'condition').map((a) => Number(a.step_key)));

const actions = rawActions.map((a, i) => {
  if (!VALID_ACTION_TYPES.includes(a.action_type)) throw new Error(`Step ${i + 1} has an invalid action_type.`);
  checkConfig(a.action_type, a.action_config, i + 1);
  const parentStepKey = (a.parent_step_key === null || a.parent_step_key === undefined || a.parent_step_key === '')
    ? null
    : Number(a.parent_step_key);
  if (parentStepKey !== null && !conditionStepKeys.has(parentStepKey)) {
    throw new Error(`Step ${i + 1} has a parent_step_key that does not point at a condition step in this automation.`);
  }
  const branch = str(a.branch) || 'default';
  if (!['default', 'true', 'false'].includes(branch)) throw new Error(`Step ${i + 1} has an invalid branch.`);
  return {
    step_key: Number(a.step_key),
    parent_step_key: parentStepKey,
    branch,
    action_type: a.action_type,
    action_config: a.action_config,
    sort_order: i,
  };
});

return [{ json: { id, name, triggerType, triggerEvent, triggerConfig, conditionTree, actions, requesterId: requester.id } }];

