WITH upd AS (
  UPDATE automations SET name = $2, trigger_type = $3, trigger_config = $4::jsonb, condition_tree = $5::jsonb, trigger_event = $7, updated_at = now()
  WHERE id = $1::int RETURNING id
),
ins AS (
  INSERT INTO automations (name, trigger_type, trigger_config, condition_tree, trigger_event, is_active, created_by, created_at, updated_at)
  SELECT $2, $3, $4::jsonb, $5::jsonb, $7, true, $6, now(), now() WHERE $1::int IS NULL RETURNING id
)
SELECT id FROM upd UNION ALL SELECT id FROM ins;

WITH deleted AS (
  DELETE FROM automation_actions WHERE automation_id = $1 AND step_key <> ALL($2::int[]) RETURNING id
)
SELECT $1 AS automation_id;

